# ## Input-specific quality filters
#
# These functions contain the only processing which differs between input types.
#
# The functions are located here because `filter_ppp` is needed for calculating the PPP origin point.

# +
def filter_ppp(df, fcfg):
    """ Filtering for PPP positions.

    1. Retain epochs with 95% sigmas below threshold (the TRACK RMS/N/NotF 
       approach is not possible, and PPP sigmas are too large for TRACK thresholds).
    2. Remove days that have insufficient observations after (1).
    """
    c = fcfg['filter_positions_ppp']
    n = len(df)
    print(f'\t Starting with {n} positions')
    df = df[(df['SigN_cm'] < c['sig_n_cm']) & (df['SigE_cm'] < c['sig_e_cm'])]
    print(f'\t {len(df)} left after sigma filter')
    daily_nobs = pd.Series(1, index=df.index).groupby(df.index.floor('1D')).transform('count')
    df = df[daily_nobs > c['min_daily_obs']]
    print(f'\t {len(df)} ({np.round(100 / max(n, 1) * len(df), 0)} %) left after removing days with <= {c["min_daily_obs"]} obs')
    return df


def average_positions(df, freq='1D', dim_cols=['x_m', 'y_m', 'z_m', 'SigN_cm', 'SigE_cm'], 
                   default_reducer='mean', extra_reducers=['std'], trim=None):
    """
    Calculate average values by integrating over the desired frequency.

    Intended use is to take short GNSS observation periods (a few hours)
    and average the position estimates into a single value for the period,
    for each of the positional dimensions.

    :param df: pd.DataFrame
    :param freq: str, desired output frequency
    :param dim_cols: list, names of columns containing the position dimensions.
    :param extra_reducers: list, name of pandas reduction methods to also run besides mean.
    :param trim: str, time amount (e.g. 1h) to trim from each side of period before averaging.

    Returns: pd.DataFrame, with columns as indicated in dim_cols (means); 
    other statistics in columns appended with name of statistic.
    """
    def _midpts(x):
        if len(x) > 0:
            start = x.index[0]
            finish = x.index[-1]
            midpt = start + ((finish - start) / 2)
            return midpt.round(args.sample_freq)
        else:
            return np.nan

    if trim:
        df = df.loc[df.index[0]+pd.Timedelta(trim):df.index[-1]-pd.Timedelta(trim)]
    # Get timestamps of midpoint in each resampled block
    midpts = df[dim_cols[0]].resample(freq).apply(_midpts)
    midpts.name = None

    store = []
    for dim in dim_cols:
        for method in ([default_reducer] + extra_reducers):
            rs = df[dim].resample('1D').apply(method)
            rs.index = midpts
            # time blocks submitted for resampling which do not contain data return NaT: get rid of these
            rs = rs[rs.index.notna()]
            rs.name = dim if method == default_reducer else f'{dim}_{method}'
            store.append(rs)
        
    return pd.DataFrame(store).T


def filter_track(data_here, fcfg):
    """ Filtering for TRACK positions.

    Identifies periods of continuous, daily/episodic and no occupation, 
    then applies the corresponding filtering to each period.
    Returns list of filtered DataFrames.
    """
    def occ_type(d, threshold_continuous=1600):
        """ Label occupation type from number of observations per day.
        2 = continuous (e.g. 10 sec) occupation, 1 = 'episodic', e.g. for an hour, 0 = no occupation
        """
        if d > threshold_continuous: return 2
        if d < threshold_continuous and d > 0: return 1
        return 0

    def process_daily_occups(df):
        """ The filtering processes for episodic/daily observations. """
        # First cull based on 'standard' TRACK statistics
        if df['RMS_mm'].isna().sum() < 1:
            df = pp.filter_positions(df, 
                                     fcfg['filter_positions_episodic']['rms'],
                                     fcfg['filter_positions_episodic']['h'],
                                     fcfg['filter_positions_episodic']['N'], 
                                     fcfg['filter_positions_episodic']['NotF']
                                    )
        else:
            print('Found NaNs in RMS_mm column, skipping filter_positions')
        if len(df) == 0:
            print('No positions left after initial filtering')
            return df
        # Now calculate single means per day of occupation
        # The idea here is that poor quality days can be identified by high standard deviations.
        means = average_positions(df, trim='1h')
        if len(means) == 0:
            means = average_positions(df)
        th = fcfg['filter_positions_episodic']['stddev']
        keep = means[(means['x_m_std'] < th) & (means['y_m_std'] < th)]
        print(f'{len(keep)} positions left after daily averaging')
        return keep

    def process_cont_occups(df):
        """ The filtering processes for continuous observations. """
        print('Filtering out bad positions (according to RMS etc)')
        n = len(df)
        print(f'\t Starting with {n} positions')
        df = pp.filter_positions(df, 
                     fcfg['filter_positions_continuous']['rms'],
                     fcfg['filter_positions_continuous']['h'],
                     fcfg['filter_positions_continuous']['N'], 
                     fcfg['filter_positions_continuous']['NotF']
                    )
        nn = len(df)
        print(f'\t {nn} ({np.round(100 / n * nn, 0)} %) left after applying filter criteria')
        if nn == 0:
            return df
        df = pp.remove_displacement_outliers(df, 
                                             args.sample_freq,
                                             fcfg['remove_displacement_outliers']['diff_x_m'],
                                             fcfg['remove_displacement_outliers']['diff_y_m'],
                                             fcfg['remove_displacement_outliers']['diff_z_m'],
                                             fcfg['remove_displacement_outliers']['median_win'],
                                             fcfg['remove_displacement_outliers']['sigma_mult'],
                                             iterations=fcfg['remove_displacement_outliers'].get('iterations', 2)
                                            )
        nnn = len(df)
        print(f'\t {nnn} ({np.round(100 / n * nnn, 0)} %) left after removing displacement outliers')
        return df

    data_ok = data_here[data_here.exclude == False]
    out = []

    # Count number of daily observations
    counts = data_ok.x_m.resample('1D').count().to_frame()
    counts['type'] = counts['x_m'].apply(occ_type)
    counts['type_roll'] = counts['type'].rolling('3D', center=True).max()

    # Find change dates
    detect = np.abs(counts['type_roll'].shift(1) - counts['type_roll'])
    dates = detect[detect > 0].index.to_list()

    # Get associated period types
    period_types = counts['type_roll'][detect > 0].to_list()

    # Create equivalent 'starting' lists that include the first period's type
    period_types_start = deepcopy(period_types)
    period_types_start.insert(0, counts['type_roll'].iloc[0])
    dates_start = deepcopy(dates)
    dates_start.insert(0, data_here.index[0])

    # Add dummy values to make lists same size as _start variants
    period_types.append(0)
    dates.append(0)

    # Process each identified period of data in turn.
    for d_st, d_en, s in zip(dates_start, dates, period_types_start):
        
        # Get the data from this period...
        if d_en == 0:
            pxyz = data_ok[d_st:]
            d_en = data_ok.index[-1]
        else:
            # pandas indexing is inclusive, so to prevent using the same data twice we
            # need to force the indexing to be 'exclusive'.
            d_en = d_en - pd.Timedelta(days=1)
            if s == 2:
                pxyz = data_ok[d_st:d_en]
            elif s == 1:
                # Try to add a couple of days from the continuous time series, to improve rolling window smoothing.
                pxyz = data_ok[d_st:d_en+pd.Timedelta(days=2)]
            elif s == 0:
                pxyz = data_ok.iloc[0:0]
            else:
                raise ValueError('Unknown occupation type.')

        message = 'Period {ds} to {de}: treating as {{type}} occupations.'.format(
                ds=d_st.strftime('%Y-%m-%d'), de=d_en.strftime('%Y-%m-%d'))

        # Now apply the correct type of filtering for the period type.
        if s == 1:
            print(message.format(type='daily'))
            pxyz = process_daily_occups(pxyz)
        elif s == 2:
            print(message.format(type='continuous'))
            pxyz = process_cont_occups(pxyz)
        elif s == 0:
            print(message.format(type='empty/ignore'))
            pxyz = data_ok.iloc[0:0]
        else:
            raise ValueError('Unknown occupation type.')

        if pxyz is not None and len(pxyz) > 0:
            # Make sure that we only save back data for the period,
            # without any data which may have been prepended/appended
            # to help with filtering edge effects.
            out.append(pxyz[d_st:d_en])
    return out


