def ax_lim(data, scl_fac):
    """ Axis limits as mean +/- scl_fac * std. dev. """
    mn = np.nanmean(data)
    stdv = np.nanstd(data)
    return (mn - scl_fac * stdv, mn + scl_fac * stdv)


def shade_exclusions(ax):
    if os.path.exists(exclusions_file) and not args.noexcl:
        excl = pd.read_csv(exclusions_file, parse_dates=['excl_start', 'excl_end'])
        for ix, row in excl.iterrows():
            ax.axvspan(row.excl_start, row.excl_end, alpha=0.1, color='tab:red')


def epoch_plotting(ax, v_ts, data_kwargs=None, error_kwargs=None):
    # Plot stepped velocities
    ax.plot(v_ts.index, v_ts['v_myr'], drawstyle='steps-post', **data_kwargs)
    # Uncertainties are plotted separately at the mid-point of each (irregular) epoch.
    mid_pt_timestamps = (v_ts.index+np.abs(v_ts.index.diff(-1)/2))
    df_plotting = pd.DataFrame({'v_myr':v_ts.v_myr, 'v_unc':v_ts.v_uncertainty_myr})
    df_plotting.index = mid_pt_timestamps
    df_plotting = df_plotting[df_plotting.index.notnull()].dropna()
    ax.errorbar(df_plotting.index, df_plotting['v_myr'], linestyle='none',
                yerr=df_plotting['v_unc'], **error_kwargs)


